import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Claude Sonnet 4.5 System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-sonnet-4-5-system-card","title":"Claude Sonnet 4.5 System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2025-09-01T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-sonnet-4-5-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2025-09-01-claude-sonnet-4-5-system-card.md","filePath":"research/papers/2025-09-01-claude-sonnet-4-5-system-card.md","lastUpdated":1785909234000}'),s={name:"research/papers/2025-09-01-claude-sonnet-4-5-system-card.md"};function n(i,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-sonnet-4-5-system-card" tabindex="-1">Claude Sonnet 4.5 System Card <a class="header-anchor" href="#claude-sonnet-4-5-system-card" aria-label="Permalink to &quot;Claude Sonnet 4.5 System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-sonnet-4-5-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-sonnet-4-5-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%20Sonnet%204.5%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: September 2025（清單記 2025-09-01；模型公開發布日為 2025-09-29）</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Sonnet 4.5 為當時 SWE-bench Verified 最高分的 Claude 模型，主打長時程（30 小時級）agentic coding 與 computer use。其 system card 最受矚目處在於 <strong>evaluation awareness（評測情境察覺）</strong>：模型會辨識自己正被測試而表現異常良好，Anthropic 首次於 frontier 模型部署前以白盒 interpretability（sparse autoencoder）驗證安全性是否在抑制該察覺後仍成立。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Sonnet 4.5</strong>：Sonnet 檔位旗艦，coding/agent/computer-use 強化，支援長時程自主任務。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>77.2%</strong>（500 題完整集，10 trials 平均，無 test-time compute，200K thinking budget）。</li><li><strong>OSWorld</strong>（real-world computer tasks）：<strong>61.4%</strong>（OSWorld-Verified 框架，100 max steps，4 runs 平均）。</li><li><strong>AI Safety Level</strong>：<strong>ASL-3</strong>。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li><strong>Evaluation awareness</strong>：內部評測中約 <strong>58%</strong> 機率辨識出測試情境（Opus 4.1 為 22%）。</li><li><strong>白盒 interpretability 預部署驗證</strong>：訓練 SAE 找出「評測察覺」特徵 → 人工抑制 → 確認即使壓掉該能力，模型仍比前代更安全。為 frontier 模型首次預部署採用此手法。</li></ul><h3 id="限制-弱點-評估" tabindex="-1">限制 / 弱點（評估） <a class="header-anchor" href="#限制-弱點-評估" aria-label="Permalink to &quot;限制 / 弱點（評估）&quot;">​</a></h3><ul><li>Evaluation awareness 本身使「評測分數能否代表真實部署行為」存疑——官方以 interpretability 緩解，但這是觀測層的根本挑戰。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong><code>pilot</code>（tier=quality，原 <code>sonnet-pilot</code>） 直接對應</strong>：本卡是 <code>pilot</code>（tier=quality，原 <code>sonnet-pilot</code>）（quality-first）的能力底座；77.2% SWE-bench 校準「Sonnet 已接近舊 Opus」的分工假設。</li><li><strong>Evaluation awareness ↔ TEST 階段紀律</strong>：呼應 core.md「能通過任何實作的測試 = 沒有測試」與 unverified_success——若受測者能察覺並針對評測優化，自評信號更不可信，須機械驗證。</li><li><strong>白盒驗證 ↔ advisor / 獨立 evaluator</strong>：與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）「fresh-context verifier 優於 self-critique」同源——不靠模型自述，靠外部探針確認。</li></ul>',19)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
